436	/// 比較元を決めていないrunに、比較元の候補として示す事実：最後に採用した変更のrunと、直前のrun。
437	#[derive(Debug)]
438	pub struct BaseCandidates {
439	    /// 最新の判断が`accepted`の変更が根拠にした、最も新しいrunとそのscore。
440	    pub accepted: Option<(String, Option<i64>)>,
441	    /// 直前のrun（[`previous_run`]）、score、最新の分析の判定（無ければ分析の状態）。
442	    pub previous: Option<(String, Option<i64>, String)>,
443	}
444	
445	impl std::fmt::Display for BaseCandidates {
446	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
447	        let score = |score: &Option<i64>| score.map_or("-".into(), |score| thousands(score as f64));
448	        let mut parts = Vec::new();
449	        // 直前のrunが最後に採用したrunでもあれば、1つにまとめる。
450	        let same =
451	            matches!((&self.accepted, &self.previous), (Some((a, _)), Some((p, _, _))) if a == p);
452	        if let Some((id, value)) = &self.accepted
453	            && !same
454	        {
455	            parts.push(format!(
456	                "last accepted {} {}",
457	                crate::runner::short_id(id),
458	                score(value)
459	            ));
460	        }
461	        if let Some((id, value, verdict)) = &self.previous {
462	            let accepted = if same { ", last accepted" } else { "" };
463	            parts.push(format!(
464	                "previous {} {} ({verdict}{accepted})",
465	                crate::runner::short_id(id),
466	                score(value)
467	            ));
468	        }
469	        write!(f, "candidates: {}", parts.join("; "))
470	    }
471	}
