473	/// `run`より前のrunから比較元の候補を探す。どちらも無ければ`None`（最初のrun）。
474	pub fn base_candidates(
475	    store: &crate::storage::Store,
476	    run: &RunManifest,
477	) -> anyhow::Result<Option<BaseCandidates>> {
478	    use rusqlite::OptionalExtension;
479	    let accepted = store
480	        .connection
481	        .query_row(
482	            "SELECT r.id, r.score FROM change_decision_runs dr
483	               JOIN change_decisions d ON d.id = dr.decision_id
484	               JOIN runs r ON r.id = dr.run_id
485	              WHERE d.status = 'accepted'
486	                AND d.created_at = (SELECT MAX(created_at) FROM change_decisions WHERE change_id = d.change_id)
487	                AND r.id != ?1 AND r.started_at < ?2
488	              ORDER BY r.started_at DESC LIMIT 1",
489	            rusqlite::params![run.id, run.started_at.to_rfc3339()],
490	            |row| Ok((row.get::<_, String>(0)?, row.get::<_, Option<i64>>(1)?)),
491	        )
492	        .optional()?;
493	    let previous = previous_run(store, run)?.map(|previous| {
494	        let verdict = previous
495	            .analyses
496	            .last()
497	            .map(|analysis| analysis.verdict.as_str().to_owned())
498	            .unwrap_or_else(|| previous.analysis_status.as_str().replace('_', " "));
499	        (previous.id, previous.benchmark.score, verdict)
500	    });
501	    if accepted.is_none() && previous.is_none() {
502	        return Ok(None);
503	    }
504	    Ok(Some(BaseCandidates { accepted, previous }))
505	}
