507	/// 同じ構成を2回以上測ってPASSした組のうち、最も新しく測った組。同じ構成とは、`config_key`が
508	/// 等しいか、`--repeat`で前のrunと同じ構成を測り直したもの（`repeat_base_run_id`）。`run`より後に
509	/// 始まったrunは入れない。scoreの振れ幅の目安で、採否の閾値ではない。
510	#[derive(Debug, Clone, PartialEq)]
511	pub struct Spread {
512	    pub commit: Option<String>,
513	    pub runs: usize,
514	    pub min: i64,
515	    pub max: i64,
516	}
517	
518	pub fn latest_spread(
519	    store: &crate::storage::Store,
520	    run: &RunManifest,
521	) -> anyhow::Result<Option<Spread>> {
522	    struct Row {
523	        id: String,
524	        config_key: Option<String>,
525	        repeats: Option<String>,
526	        commit: Option<String>,
527	        score: i64,
528	    }
529	    let mut statement = store.connection.prepare(
530	        "SELECT id, config_key, CASE WHEN repeat_reason IS NOT NULL THEN repeat_base_run_id END,
531	                commit_hash, score
532	           FROM runs
533	          WHERE passed = 1 AND state = 'complete' AND score IS NOT NULL AND started_at <= ?1
534	          ORDER BY started_at, id",
535	    )?;
536	    let rows = statement
537	        .query_map([run.started_at.to_rfc3339()], |row| {
538	            Ok(Row {
539	                id: row.get(0)?,
540	                config_key: row.get(1)?,
541	                repeats: row.get(2)?,
542	                commit: row.get(3)?,
543	                score: row.get(4)?,
544	            })
545	        })?
546	        .collect::<rusqlite::Result<Vec<_>>>()?;
547	    // 組を、最初に測ったrunの位置で表す。
548	    let mut group = Vec::<usize>::with_capacity(rows.len());
549	    let mut by_key = BTreeMap::<&str, usize>::new();
550	    let mut by_id = BTreeMap::<&str, usize>::new();
551	    for (position, row) in rows.iter().enumerate() {
552	        let same = row
553	            .repeats
554	            .as_deref()
555	            .and_then(|base| by_id.get(base).map(|index| group[*index]))
556	            .or_else(|| {
557	                row.config_key
558	                    .as_deref()
559	                    .and_then(|key| by_key.get(key).map(|index| group[*index]))
560	            })
561	            .unwrap_or(position);
562	        group.push(same);
563	        by_id.insert(&row.id, position);
564	        if let Some(key) = row.config_key.as_deref() {
565	            by_key.insert(key, position);
566	        }
567	    }
568	    let mut groups = BTreeMap::<usize, (usize, Vec<usize>)>::new();
569	    for (position, first) in group.iter().enumerate() {
570	        let entry = groups.entry(*first).or_insert((position, Vec::new()));
571	        entry.0 = position;
572	        entry.1.push(position);
573	    }
574	    Ok(groups
575	        .into_values()
576	        .filter(|(_, members)| members.len() >= 2)
577	        .max_by_key(|(last, _)| *last)
578	        .map(|(last, members)| {
579	            let scores = members.iter().map(|index| rows[*index].score);
580	            Spread {
581	                commit: rows[last].commit.clone(),
582	                runs: members.len(),
583	                min: scores.clone().min().unwrap_or_default(),
584	                max: scores.max().unwrap_or_default(),
585	            }
586	        }))
587	}
